import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with shared memory tiling
matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size for shared memory
#define TILE_SIZE 32

__global__ void matmul_kernel_tiled(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    int row = blockRow * TILE_SIZE + threadIdx.y;
    int col = blockCol * TILE_SIZE + threadIdx.x;

    float Cvalue = 0.0f;

    // Loop over the tiles required to compute the Cvalue
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles into shared memory
        int Arow = blockRow * TILE_SIZE + threadIdx.y;
        int Acol = t * TILE_SIZE + threadIdx.x;
        if (Arow < N && Acol < N) {
            sA[threadIdx.y][threadIdx.x] = A[Arow * N + Acol];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        int Brow = t * TILE_SIZE + threadIdx.y;
        int Bcol = blockCol * TILE_SIZE + threadIdx.x;
        if (Brow < N && Bcol < N) {
            sB[threadIdx.y][threadIdx.x] = B[Brow * N + Bcol];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        __syncthreads();

        // Perform matrix multiplication on the tiles
        for (int k = 0; k < TILE_SIZE; ++k) {
            Cvalue += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}

torch::Tensor matmul_cuda_tiled(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    int BLOCK_SIZE = TILE_SIZE;
    dim3 dimBlock(BLOCK_SIZE, BLOCK_SIZE);
    dim3 dimGrid((N + dimBlock.x - 1) / dimBlock.x, (N + dimBlock.y - 1) / dimBlock.y);

    matmul_kernel_tiled<<<dimGrid, dimBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

